import { Bps } from './bps.js';
describe('Bps', function() {
    describe('fromSharePercent', function() {
        it('should convert decimal percent to bps without float error', function() {
            expect(Bps.fromSharePercent(84.45).value).toBe(8445n);
        });
        it('should parse percent from string', function() {
            expect(Bps.fromSharePercent('84.45').value).toBe(8445n);
        });
        it('should handle integer percent', function() {
            expect(Bps.fromSharePercent(90).value).toBe(9000n);
        });
        it('should handle zero', function() {
            expect(Bps.fromSharePercent(0).value).toBe(0n);
        });
        it('should preserve negative sign for decimal percent', function() {
            expect(function() {
                return Bps.fromSharePercent(-0.5);
            }).toThrow(/invalid bps/);
            expect(function() {
                return Bps.fromSharePercent(-1.5);
            }).toThrow(/invalid bps/);
        });
    });
});
